'use strict';

/**
 * Shared TomSelect bootstrap for the paper-filter <select multiple> fields
 * generated by Episciences_View_Helper_PaperFilter (status, ratingStatus,
 * vid, sid, editors, reviewers, doi, repositories). Used by
 * administratepaper/list.phtml, paper/submitted (via author_papers_list.phtml
 * partial) and paper/ratings.phtml.
 */

/**
 * Tom Select's checkbox_options plugin re-renders a real, natively focusable
 * <input type="checkbox"> inside every .option on each render pass (typing,
 * dropdown open). Those checkboxes duplicate the selection state already
 * exposed via role="option"/aria-selected on the option itself, so left
 * alone they become extra unlabelled Tab stops. Strip them from the tab
 * order and hide them from assistive tech instead.
 * @param {object} ts - Tom Select instance
 */
function patchCheckboxOptionsA11y(ts) {
    function hideCheckboxes() {
        ts.dropdown_content
            .querySelectorAll('input[type="checkbox"]')
            .forEach(function (checkbox) {
                checkbox.setAttribute('tabindex', '-1');
                checkbox.setAttribute('aria-hidden', 'true');
            });
    }

    hideCheckboxes();
    ts.on('type', hideCheckboxes);
    ts.on('dropdown_open', hideCheckboxes);
}

/**
 * Enhance the given <select> ids with Tom Select, skipping any id that is
 * absent from the page (fields like editors/reviewers/doi/repositories only
 * render for users allowed to manage papers) or already enhanced.
 * @param {string[]} ids
 * @param {{ plugins?: string[] }} [options]
 * @returns {object[]} the Tom Select instances created, in id order
 */
function initTomSelectFilters(ids, options) {
    if (typeof TomSelect === 'undefined') return [];

    var plugins = (options && options.plugins) || ['remove_button'];
    var instances = [];

    ids.forEach(function (id) {
        var el = document.getElementById(id);
        if (!el || el.tomselect) return;

        var firstOption = el.querySelector('option[value=""]');
        var placeholder = firstOption ? firstOption.textContent.trim() : '';

        var ts = new TomSelect(el, {
            plugins: plugins,
            maxOptions: null,
            placeholder: placeholder,
            onItemAdd: function () {
                this.setTextboxValue('');
            },
        });

        el.style.setProperty('display', 'none', 'important');
        ts.wrapper.classList.remove('form-control');

        // Tom Select repoints the original <label for="id"> to its own
        // focusable control and wires aria-labelledby automatically when it
        // finds that label. Fall back to aria-label only if that didn't happen.
        if (!ts.control_input.hasAttribute('aria-labelledby')) {
            var label = document.querySelector('label[for="' + id + '"]');
            if (label) {
                ts.control_input.setAttribute(
                    'aria-label',
                    label.textContent.trim()
                );
            }
        }

        if (plugins.indexOf('checkbox_options') !== -1) {
            patchCheckboxOptionsA11y(ts);
        }

        instances.push(ts);
    });

    return instances;
}

/**
 * Same as initTomSelectFilters, but waits for DOMContentLoaded when the
 * TomSelect library script hasn't finished loading/executing yet.
 * @param {string[]} ids
 * @param {{ plugins?: string[] }} [options]
 */
function bootTomSelectFilters(ids, options) {
    if (typeof TomSelect !== 'undefined') {
        initTomSelectFilters(ids, options);
    } else {
        document.addEventListener('DOMContentLoaded', function () {
            initTomSelectFilters(ids, options);
        });
    }
}

if (typeof module !== 'undefined') {
    module.exports = {
        initTomSelectFilters,
        bootTomSelectFilters,
        patchCheckboxOptionsA11y,
    };
}
